const body = $input.first().json.body || $input.first().json;
let expected = '';
try { expected = $env.SIGA_CLAUDE_WEBHOOK_TOKEN || ''; } catch(e) {}
if (expected && body.siga_token !== expected) { throw new Error('Unauthorized'); }
const { entity_type, entity_id, data_base64 } = body;
if (!entity_type || !entity_id || !data_base64) { throw new Error('Missing fields'); }
if (!['equipment','accessory','consumable'].includes(entity_type)) {
  throw new Error('Invalid entity_type: ' + entity_type);
}
const ts = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19);
const role = body.role || 'overview';
const origFilename = body.filename || 'photo.jpg';
const ext = origFilename.split('.').pop().toLowerCase();
const drive_filename = entity_type + '_' + entity_id + '_' + role + '_' + ts + '.' + ext;
const ingestion_id = body.ingestion_id || ('CLAUDE-' + new Date().toISOString().replace(/[-T:.Z]/g,'').slice(0,14));
let folder_id = '';
try { folder_id = $env.SIGA_CLAUDE_FOLDER_ID || ''; } catch(e) {}
if (!folder_id) { throw new Error('SIGA_CLAUDE_FOLDER_ID not set'); }
return [{ json: { entity_type, entity_id, role, filename: origFilename,
  mime_type: body.mime_type || 'image/jpeg', data_base64: body.data_base64,
  ingestion_id, drive_filename, folder_id } }];

const item = $input.first();
const buffer = Buffer.from(item.json.data_base64, 'base64');
const binary = await this.helpers.prepareBinaryData(
  buffer,
  item.json.drive_filename,
  item.json.mime_type
);
return [{
  json: {
    entity_type: item.json.entity_type,
    entity_id: item.json.entity_id,
    role: item.json.role,
    filename: item.json.filename,
    mime_type: item.json.mime_type,
    ingestion_id: item.json.ingestion_id,
    drive_filename: item.json.drive_filename,
    folder_id: item.json.folder_id
  },
  binary: { data: binary }
}];

// Recombine Drive upload result with original context
const driveResult = $input.first().json;
const ctx = $('Decode Base64').item.json;

const file_id = driveResult.id || '';
const web_view_link = driveResult.webViewLink ||
  (file_id ? `https://drive.google.com/file/d/${file_id}/view?usp=drivesdk` : '');

return [{
  json: {
    entity_type: ctx.entity_type,
    entity_id: ctx.entity_id,
    role: ctx.role,
    filename: ctx.drive_filename,
    mime_type: ctx.mime_type,
    ingestion_id: ctx.ingestion_id,
    folder_id: ctx.folder_id,
    file_id,
    web_view_link
  }
}];
